SELECT id, user_id, channel_type, channel_value, verified_at, created_at
FROM user_channels
WHERE channel_type = #{type} AND channel_value = #{value}

SELECT id, user_id, channel_type, channel_value, verified_at, created_at
FROM user_channels
WHERE id = #{id}

SELECT id, user_id, channel_type, channel_value, verified_at, created_at
FROM user_channels
WHERE user_id = #{userId}
